import React,{useEffect,useRef} from 'react';
import {useDialog} from '../../dialog.tsx';
export function InternalPoints({points=[],chapters,onChange,storyAxis}){
 const {confirm}=useDialog(),alive=useRef(true),latest=useRef({points,onChange});latest.current={points,onChange};
 useEffect(()=>()=>{alive.current=false;},[]);
 const update=(id,patch)=>latest.current.onChange(latest.current.points.map(p=>p.id===id?{...p,...patch}:p));
 const storyMode=async(id,mode)=>{
  const original=latest.current.points.find(p=>p.id===id);if(!original||mode==='legacy')return;
  if(Number.isFinite(original.location?.story)&&!await confirm(mode==='bound'?'将旧固定坐标明确改为跟随剧情卡起点？原数值不会自动换算成日期，叙述位置保持不变。':'将这个旧故事坐标改为待定？仅清除故事定位，叙述位置保持不变。'))return;
  if(!alive.current)return;const point=latest.current.points.find(p=>p.id===id);if(point)update(id,{location:{...point.location,story:mode==='bound'?{binding:{kind:'card',offset:0}}:null}});
 };
 return <details><summary>内部关键点 · {points.length}</summary><p className="muted">{storyAxis?'故事绑定点跟随剧情卡移动；未安排卡片时保持待定。旧固定坐标保留为未换算，不自动套用新历法。叙述位置不变。':'关键点可固定在指定章节或旧故事坐标；开启独立故事轴后，可明确改为跟随剧情卡。'}关系变化仍在专门入口编辑。</p>{points.map(p=>{const story=p.location?.story,binding=story?.binding,legacy=Number.isFinite(story);return <section className="structure-entry" key={p.id}><label>关键点名称<input value={p.title||''} placeholder={p.relationships?.length?'关系变化点':'例如：发现线索'} onChange={e=>update(p.id,{title:e.target.value})}/></label>{p.relationships?.length?<small>包含 {p.relationships.length} 条关系变化，请从“管理节点”调整位置。</small>:<><label>章节<select value={p.location?.narration?.chapterId||''} onChange={e=>update(p.id,{location:{...p.location,narration:e.target.value?{chapterId:e.target.value,offset:p.location?.narration?.offset||0}:null}})}><option value="">暂不安排</option>{chapters.map(c=><option key={c.id} value={c.id}>{c.title}</option>)}</select></label>{p.location?.narration&&<label>章内位置（%）<input type="number" min="0" max="99" value={Math.round(p.location.narration.offset*100)} onChange={e=>update(p.id,{location:{...p.location,narration:{...p.location.narration,offset:Number(e.target.value)/100}}})}/></label>}
 {storyAxis?<><label>故事时间定位<select aria-label="关键点故事定位方式" value={binding?.kind==='card'?'bound':legacy?'legacy':'pending'} onChange={e=>storyMode(p.id,e.target.value)}><option value="bound">跟随剧情卡</option><option value="pending">故事时间待定</option>{legacy&&<option value="legacy">旧固定坐标 · 待换算</option>}</select></label>{binding?.kind==='card'?<label>相对{binding.ratio?`卡片 ${binding.ratio*100}% 位置`:'剧情卡起点'}的天数<input aria-label="关键点相对天数" type="number" step="1" required value={binding.offset??0} onChange={e=>{if(e.target.value!==''&&!Number.isSafeInteger(Number(e.target.value)))return;update(p.id,{location:{...p.location,story:{binding:{...binding,offset:e.target.value===''?'':Number(e.target.value)}}}});}}/><small>0 表示该位置当天。卡片移动时跟随；卡片未安排时不推算日期。</small></label>:legacy?<p className="u-boundary">旧坐标 {story} 保留 · 未映射到当前历法。更改定位方式前会请你确认。</p>:<small>尚未安排故事日期，不影响章节位置。</small>}</>:<label>旧故事坐标<input type="number" step="any" value={legacy?story:''} onChange={e=>update(p.id,{location:{...p.location,story:e.target.value===''?null:Number(e.target.value)}})}/></label>}
 <button type="button" onClick={()=>onChange(points.filter(x=>x.id!==p.id))}>移除关键点</button></>}</section>;})}<button type="button" onClick={()=>onChange([...points,{id:crypto.randomUUID(),title:'',order:points.length,location:storyAxis?{story:{binding:{kind:'card',offset:0}}}:{},relationships:[]}])}>＋ 添加关键点</button></details>;
}
